class Solution {
public:
    int getSum(int a, int b) {
        const unsigned int MASK = 0xffffffffu;
        unsigned int ua = static_cast<unsigned int>(a);
        unsigned int ub = static_cast<unsigned int>(b);
        while (ub != 0) {
            unsigned int carry = (ua & ub) << 1;
            ua = (ua ^ ub) & MASK;
            ub = carry & MASK;
        }
        return static_cast<int>(ua);
    }
};
